package com.aistock.market.marketlifecycle;
import com.aistock.common.*;import com.fasterxml.jackson.databind.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class MarketLocalUseProofHttpTest {
 final ObjectMapper json=new ObjectMapper();final String op=UUID.randomUUID().toString();MarketComparisonUseOwner owner;MockMvc mvc;String uri;
 @BeforeEach void setup(){owner=mock(MarketComparisonUseOwner.class);uri="/internal/v1/market-version-use-proofs/COMPARISON_EVIDENCE_PUBLISH/"+op;mvc=MockMvcBuilders.standaloneSetup(new MarketLocalUseProofController(owner)).setControllerAdvice(new ApiExceptionHandler()).addFilters(new MarketUseProofAccessFilter("private",json)).build();}
 @Test void authenticationPrecedesQueryParsingAndRejectsDuplicateTokens()throws Exception{mvc.perform(get(uri).param("generation","bad")).andExpect(status().isUnauthorized()).andExpect(header().string("Cache-Control","no-store"));mvc.perform(get(uri).header("X-Service-Token","private","other").param("generation","1")).andExpect(status().isUnauthorized());verifyNoInteractions(owner);}
 @Test void onlyBodylessGetWithExactSingleGenerationIsAllowed()throws Exception{mvc.perform(post(uri).header("X-Service-Token","private").content("{}")).andExpect(status().isNotFound());mvc.perform(get(uri).header("X-Service-Token","private").content("{}")).andExpect(status().isBadRequest());mvc.perform(get(uri).header("X-Service-Token","private").param("generation","1","2")).andExpect(status().isBadRequest());mvc.perform(get(uri).header("X-Service-Token","private").param("generation","1").param("state","SUCCEEDED")).andExpect(status().isBadRequest());verifyNoInteractions(owner);}
 @Test void proofIsInternalNoStoreAndDoesNotAcceptCallerTerminalState()throws Exception{when(owner.proof(UUID.fromString(op),"1")).thenReturn(json.createObjectNode().put("state","FAILED"));mvc.perform(get(uri).header("X-Service-Token","private").param("generation","1")).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("$.data.state").value("FAILED"));verify(owner).proof(UUID.fromString(op),"1");}
 @Test void missingServerTokenFailsClosed()throws Exception{var off=MockMvcBuilders.standaloneSetup(new MarketLocalUseProofController(owner)).addFilters(new MarketUseProofAccessFilter("",json)).build();off.perform(get(uri).header("X-Service-Token","private")).andExpect(status().isServiceUnavailable());verifyNoInteractions(owner);}

 @Test void capabilitiesAreAuthenticatedAndAdvertiseOnlyActuallyImplementedPurposes()throws Exception{mvc.perform(get("/internal/v1/market-version-use-proofs/capabilities")).andExpect(status().isUnauthorized());mvc.perform(get("/internal/v1/market-version-use-proofs/capabilities").header("X-Service-Token","private")).andExpect(status().isOk()).andExpect(jsonPath("$.data.protocolVersion").value("market-version-use-v1")).andExpect(jsonPath("$.data.supportedPurposes.length()").value(2)).andExpect(jsonPath("$.data.enabledPurposes.length()").value(0)).andExpect(jsonPath("$.data.consumerIntegration").value("PARTIAL")).andExpect(jsonPath("$.data.actionsEnabled").value(false));}
 @Test void alertProofDispatchUsesActualOwnerWithoutAcceptingCallerState()throws Exception{var alert=mock(com.aistock.market.alert.AlertLocalUseOwner.class);when(alert.proof(UUID.fromString(op),"1")).thenReturn(json.createObjectNode().put("state","FAILED"));var both=MockMvcBuilders.standaloneSetup(new MarketLocalUseProofController(owner,alert)).setControllerAdvice(new ApiExceptionHandler()).addFilters(new MarketUseProofAccessFilter("private",json)).build();String path="/internal/v1/market-version-use-proofs/ALERT_EVIDENCE_PUBLISH/"+op;both.perform(get(path)).andExpect(status().isUnauthorized());both.perform(get(path).header("X-Service-Token","private").param("generation","1")).andExpect(status().isOk()).andExpect(jsonPath("$.data.state").value("FAILED"));verify(alert).proof(UUID.fromString(op),"1");}

}
